CREATE VIEW RedGate.FeedbackAuditSummary AS
SELECT AuditID, CustomerID, CreatedAt
FROM RedGate.FeedbackAudit;

-- Drop the view first since it may reference the column IF EXISTS (SELECT * FROM sys.views WHERE object_id = OBJECT_ID(N'RedGate.FeedbackAuditSummary')) BEGIN DROP VIEW RedGate.FeedbackAuditSummary END
-- Drop the column ALTER TABLE RedGate.FeedbackAudit DROP COLUMN Note;
-- Recreate the view without the Note column CREATE VIEW RedGate.FeedbackAuditSummary AS SELECT AuditID, CustomerID, CreatedAt FROM RedGate.FeedbackAudit;
